using System.Collections;
using LittleLeo.Variables;
using NaughtyAttributes;
using UnityEngine;
using UnityEngine.Events;

namespace Astrea;

public class ZoomableInstance : MonoBehaviour
{
	[Header("Components")]
	[SerializeField]
	protected bool enableActionDescriptionPanel;

	[SerializeField]
	[ShowIf("enableActionDescriptionPanel")]
	private GameObject actionDescriptionPanelPrefab;

	[SerializeField]
	[ShowIf("enableActionDescriptionPanel")]
	protected Transform actionDescriptionPanelPosition;

	[SerializeField]
	[ShowIf("enableActionDescriptionPanel")]
	private FloatReference tooltipDelayReference;

	[SerializeField]
	private bool zoomAnotherTransform;

	[SerializeField]
	[ShowIf("zoomAnotherTransform")]
	private Transform transformToZoom;

	[Header("Zoom Animation")]
	[SerializeField]
	private FloatReference zoomDurationReference;

	[SerializeField]
	private AnimationCurveReference zoomCurveReference;

	[SerializeField]
	private float zoomScale;

	[Header("Unity Event")]
	[SerializeField]
	private bool enableOnMouseOverEvent;

	[SerializeField]
	[ShowIf("enableOnMouseOverEvent")]
	private UnityEvent onMouseOverEvent;

	[SerializeField]
	private bool enableOnMouseExitEvent;

	[SerializeField]
	[ShowIf("enableOnMouseExitEvent")]
	private UnityEvent onMouseExitEvent;

	[Header("Highlight")]
	[SerializeField]
	private Vector3 offsetHighlightPosition;

	[SerializeField]
	private bool ignoreHighlight;

	[SerializeField]
	private bool ignoreChangeIconTinyObject;

	[SerializeField]
	private bool useActionDescriptionDelay;

	[SerializeField]
	private bool enableCustomHighlightSize;

	[SerializeField]
	[ShowIf("enableCustomHighlightSize")]
	private Vector2 customHighlightSize;

	[SerializeField]
	private bool enableCustomHighlightGameObject;

	[SerializeField]
	[ShowIf("enableCustomHighlightGameObject")]
	private GameObject customHighlightGameObject;

	[SerializeField]
	private bool enableDelayHighlight;

	[SerializeField]
	[ShowIf("enableDelayHighlight")]
	private float delayHighlight;

	[SerializeField]
	private bool enableCustomPixelsPerUnitMultiplier;

	[SerializeField]
	[ShowIf("enableCustomPixelsPerUnitMultiplier")]
	private float customPixelsPerUnitMultiplier = 1f;

	[Header("Camera")]
	[SerializeField]
	protected CameraEnum cameraEnum;

	private Coroutine zoomingCoroutine;

	[ShowNonSerializedField]
	private Vector3 defaultScale;

	protected bool mouseOver;

	protected Coroutine tooltipDelayCoroutine;

	protected Coroutine onMouseOverFrameDelayCoroutine;

	protected ActionDescriptionPanel actionDescriptionPanel;

	protected bool lockMouseOver;

	public bool EnableActionDescriptionPanel => enableActionDescriptionPanel;

	public FloatReference TooltipDelayReference => tooltipDelayReference;

	public Vector3 OffsetHighlightPosition => offsetHighlightPosition;

	public bool IgnoreHighlight => ignoreHighlight;

	public bool IgnoreChangeIconTinyObject => ignoreChangeIconTinyObject;

	public bool UseActionDescriptionDelay => useActionDescriptionDelay;

	public bool EnableCustomHighlightSize => enableCustomHighlightSize;

	public Vector2 CustomHighlightSize => customHighlightSize;

	public bool EnableCustomHighlightGameObject => enableCustomHighlightGameObject;

	public GameObject CustomHighlightGameObject => customHighlightGameObject;

	public bool EnableDelayHighlight => enableDelayHighlight;

	public float DelayHighlight => delayHighlight;

	public bool EnableCustomPixelsPerUnitMultiplier => enableCustomPixelsPerUnitMultiplier;

	public float CustomPixelsPerUnitMultiplier => customPixelsPerUnitMultiplier;

	public CameraEnum CameraEnum => cameraEnum;

	public void SetEnableActionDescriptionPanel(bool value)
	{
		enableActionDescriptionPanel = value;
	}

	public void SetEnableDelayHighlight(bool value)
	{
		enableDelayHighlight = value;
	}

	public void SetCameraEnum(CameraEnum value)
	{
		cameraEnum = value;
	}

	protected virtual void Awake()
	{
		defaultScale = (zoomAnotherTransform ? transformToZoom.localScale : base.transform.localScale);
	}

	public void SetDefaultScale(float newScaleFactor)
	{
		defaultScale = Vector3.one * newScaleFactor;
	}

	protected virtual void OnEnable()
	{
		InvokeAlternatives.InvokeAfterFrame(this, delegate
		{
			ResetToDefaultScale();
		});
	}

	private void ResetToDefaultScale()
	{
		if (zoomAnotherTransform)
		{
			transformToZoom.localScale = defaultScale;
		}
		else
		{
			base.transform.localScale = defaultScale;
		}
	}

	public virtual void InitializeActionDescriptionPanel()
	{
	}

	protected void ResetScale()
	{
		if (tooltipDelayCoroutine != null)
		{
			StopCoroutine(tooltipDelayCoroutine);
		}
		ResetToDefaultScale();
	}

	public virtual void OnMouseOver()
	{
		if (!mouseOver && (bool)this && onMouseOverFrameDelayCoroutine == null && base.gameObject.activeInHierarchy)
		{
			onMouseOverFrameDelayCoroutine = StartCoroutine(OnMouseOverFrameDelay(showTooltip: true));
		}
	}

	private IEnumerator OnMouseOverFrameDelay(bool showTooltip)
	{
		yield return InvokeAlternatives.WaitOneFrame();
		if (ReferenceSingleton<InputManager>.Instance.IsJoystickBeingUsed)
		{
			yield return new WaitUntil(() => ReferenceSingleton<InputManager>.Instance.IsJoystickInteractionEnabled);
		}
		mouseOver = true;
		Zoom(zoomingIn: true);
		if (showTooltip)
		{
			ShowTooltip();
		}
		ReferenceSingleton<InputManager>.Instance.MoveToNextZoomableInstance(this);
		if (enableOnMouseOverEvent)
		{
			onMouseOverEvent.Invoke();
		}
		onMouseOverFrameDelayCoroutine = null;
	}

	public void ShowTooltip()
	{
		if (base.gameObject.activeInHierarchy && enableActionDescriptionPanel)
		{
			tooltipDelayCoroutine = StartCoroutine(TooltipDelayCoroutine());
		}
	}

	public void UpdateTooltipPosition()
	{
		if (actionDescriptionPanel != null)
		{
			actionDescriptionPanel.SetPosition(cameraEnum, actionDescriptionPanelPosition.position);
		}
	}

	private IEnumerator TooltipDelayCoroutine()
	{
		yield return new WaitForSecondsRealtime(tooltipDelayReference.Value);
		if (enableActionDescriptionPanel)
		{
			if (actionDescriptionPanel == null)
			{
				GameObject @object = ReferenceSingleton<PoolHandler>.Instance.GetObject(actionDescriptionPanelPrefab.name);
				actionDescriptionPanel = @object.GetComponent<ActionDescriptionPanel>();
				actionDescriptionPanel.SetPosition(cameraEnum, actionDescriptionPanelPosition.position);
			}
			if (GameScenesUtils.IsBattleScene())
			{
				ReferenceSingleton<BattleHandler>.Instance.SetActionDescriptionActionInstance(null);
			}
			InitializeActionDescriptionPanel();
			InvokeAlternatives.InvokeAfterFrame(this, delegate
			{
				actionDescriptionPanel.Fade(fadeIn: true, null, tooltipDelayReference.Value);
			});
		}
		tooltipDelayCoroutine = null;
	}

	public void OnMouseOverNoActionDescriptionPanel()
	{
		if (!mouseOver && onMouseOverFrameDelayCoroutine == null)
		{
			onMouseOverFrameDelayCoroutine = StartCoroutine(OnMouseOverFrameDelay(showTooltip: false));
		}
	}

	public virtual void OnMouseExit()
	{
		if (lockMouseOver)
		{
			return;
		}
		if (onMouseOverFrameDelayCoroutine != null)
		{
			StopCoroutine(onMouseOverFrameDelayCoroutine);
			onMouseOverFrameDelayCoroutine = null;
		}
		if (!mouseOver)
		{
			return;
		}
		if (enableActionDescriptionPanel)
		{
			if (tooltipDelayCoroutine != null)
			{
				StopCoroutine(tooltipDelayCoroutine);
			}
			else
			{
				HideTooltip();
			}
		}
		Zoom(zoomingIn: false);
		mouseOver = false;
		ReferenceSingleton<InputManager>.Instance.FadeHighlight(this);
		if (enableOnMouseExitEvent)
		{
			onMouseExitEvent.Invoke();
		}
	}

	public void HideTooltip()
	{
		if (actionDescriptionPanel != null)
		{
			actionDescriptionPanel.ActionDescriptionInstancePositioner.ResetOverridePositions();
			actionDescriptionPanel.Fade(fadeIn: false, delegate
			{
				ReferenceSingleton<PoolHandler>.Instance.StoreObject(actionDescriptionPanel.gameObject);
				actionDescriptionPanel = null;
			}, tooltipDelayReference.Value);
		}
	}

	public void OnMouseExitOnlyTooltip()
	{
		if (!lockMouseOver && mouseOver && enableActionDescriptionPanel)
		{
			if (tooltipDelayCoroutine != null)
			{
				StopCoroutine(tooltipDelayCoroutine);
			}
			else
			{
				HideTooltip();
			}
		}
	}

	protected void Zoom(bool zoomingIn)
	{
		if (zoomingCoroutine != null)
		{
			StopCoroutine(zoomingCoroutine);
		}
		Vector3 startingScale = (zoomAnotherTransform ? transformToZoom.localScale : base.transform.localScale);
		Vector3 targetScale = defaultScale * zoomScale;
		if (!zoomingIn)
		{
			targetScale = defaultScale;
		}
		if (base.gameObject.activeInHierarchy)
		{
			Transform transf = (zoomAnotherTransform ? transformToZoom : base.transform);
			zoomingCoroutine = StartCoroutine(CoroutineUtility.CurveRoutine(zoomDurationReference.Value, zoomCurveReference.Value, delegate(float t, float v)
			{
				transf.localScale = Vector3.Lerp(startingScale, targetScale, v);
			}, isRealtime: true));
		}
	}
}
